css:
.about-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 20px; padding: 22px;
  height: 100%; display: flex; flex-direction: column; gap: 14px;
  position: relative; overflow: hidden;
  max-width: 380px;
}
.about-card .texture {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(45deg, #0a0a0a, #0a0a0a 12px, #111 12px, #111 13px);
  opacity: 0.6;
}
.about-card .row-top {
  position: relative; display: flex; justify-content: space-between; align-items: center;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; color: #666; letter-spacing: 0.15em; text-transform: uppercase;
}
/* O card acompanha a altura da coluna de texto ao lado, e a foto ocupa essa
   altura mantendo a proporção do retrato — em pé e centralizada, sem corte. */
.about-card .photo-slot {
  position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column;
}
.photo-box {
  flex: 1; min-height: 0; width: auto; aspect-ratio: 2848 / 4288; margin: 0 auto;
  background: var(--bg); border: 1px solid var(--border-alt); border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.photo-box span { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: #444; letter-spacing: 0.15em; text-transform: uppercase; }
/* Fora do fluxo de propósito: se a imagem entra no cálculo, a proporção dela
   estica o card e o texto é que passa a acompanhar a foto. Assim é o card de
   texto que manda na altura, e a foto preenche o que sobrar. */
.photo-box img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover; object-position: center top;
  filter: contrast(1.08) saturate(0.9) brightness(0.95);
}
.photo-box::after {
  content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  box-shadow: inset 0 0 24px 6px rgba(0, 0, 0, 0.65);
  background: linear-gradient(180deg, rgba(0,0,0,0.15) 0%, rgba(0,0,0,0) 30%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.35) 100%);
}
.about-card .name-row { position: relative; }
.about-card .name-row .name { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 28px; letter-spacing: -0.02em; line-height: 1; }
.about-card .name-row .role { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--accent); letter-spacing: 0.15em; text-transform: uppercase; margin-top: 6px; }

@media (max-width: 900px) {
  .about-card { height: auto; max-width: 380px; margin: 0 auto; }
  .photo-box { flex: none; width: 100%; }
}
